def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # In these examples, the fill color depends on the size of the enclosed square.
    # Interior dimensions 3, 5, and 7 map to colors 8, 4, and 3.
    color_by_interior_area = {9: 8, 25: 4, 49: 3}
    for r0 in range(h):
        for r1 in range(r0 + 2, h):
            for c0 in range(w):
                for c1 in range(c0 + 2, w):
                    if (all(grid[r0][c] == 2 and grid[r1][c] == 2 for c in range(c0, c1 + 1))
                        and all(grid[r][c0] == 2 and grid[r][c1] == 2 for r in range(r0, r1 + 1))):
                        area = (r1 - r0 - 1) * (c1 - c0 - 1)
                        color = color_by_interior_area.get(area)
                        if color is not None:
                            for r in range(r0 + 1, r1):
                                for c in range(c0 + 1, c1):
                                    if grid[r][c] == 0:
                                        out[r][c] = color
    return out
